WITH product_summary AS (SELECT product_id, ROUND(STDDEV(revenue), 2) AS stddev_revenue, ROUND(AVG(units), 2) AS avg_units FROM store_sales GROUP BY product_id) SELECT p.id, p.category, p.stock_qty, ps.stddev_revenue, ps.avg_units FROM products p LEFT JOIN product_summary ps ON p.id = ps.product_id ORDER BY p.category ASC
